.fx-mdl{position:relative;width:min(920px,100%);height:560px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text))}.fx-mdl .pg{position:absolute;inset:0;padding:1.2em 1.5em;display:flex;flex-direction:column;gap:1em;overflow:hidden}
.fx-mdl .nv{display:flex;align-items:center;gap:1em;padding-bottom:.9em;border-bottom:1px solid var(--border)}
.fx-mdl .nv b{font:700 1.05em var(--font-heading);display:flex;align-items:center;gap:.5em}.fx-mdl .nv b::before{content:"";width:.9em;height:.9em;border-radius:30%;background:var(--accent)}
.fx-mdl .nv i{width:3.4em;height:.55em;border-radius:9px;background:var(--border)}.fx-mdl .nv i:nth-of-type(1){margin-left:auto}
.fx-mdl .pg h2{font-size:clamp(1.5em,4vw,2.1em);max-width:18ch;margin-top:.5em}
.fx-mdl .pg .lede{opacity:.66;max-width:44ch}
.fx-mdl .pg .row{display:flex;gap:.7em;flex-wrap:wrap;margin-top:.2em}
.fx-mdl .pg .sk{display:grid;grid-template-columns:repeat(3,1fr);gap:.8em;margin-top:auto}
.fx-mdl .pg .sk div{height:5.2em;border-radius:var(--radius);border:1px solid var(--border);background:linear-gradient(135deg,color-mix(in srgb,var(--primary) 10%,transparent),color-mix(in srgb,var(--accent) 12%,transparent))}
@media(max-width:560px){.fx-mdl .pg .sk{grid-template-columns:1fr 1fr}.fx-mdl .pg .sk div:nth-child(3){display:none}.fx-mdl .nv i{display:none}}
.fx-mdl .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.7em 1.15em;border-radius:var(--radius);font:600 .92em var(--font-body);cursor:pointer;border:1px solid var(--border);background:transparent;color:var(--text);transition:background calc(.2s/var(--speed)),color calc(.2s/var(--speed)),transform calc(.2s/var(--speed)),border-color calc(.2s/var(--speed))}
.fx-mdl .btn:hover{border-color:var(--primary);color:var(--primary)}
.fx-mdl .btn.pri{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-mdl .btn.pri:hover{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-mdl .btn.acc{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-mdl .btn:active{transform:translateY(1px)}
.fx-mdl :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-mdl .scrim{position:absolute;inset:0;z-index:20;display:grid;place-items:center;padding:1em;background:color-mix(in srgb,#0b0e14 48%,transparent);backdrop-filter:blur(2px);visibility:hidden;opacity:0;transition:opacity calc(.25s/var(--speed)),visibility 0s linear calc(.25s/var(--speed))}
.fx-mdl .scrim.open{visibility:visible;opacity:1;transition-delay:0s}
.fx-mdl .dlg{width:min(440px,100%);max-height:100%;overflow:auto;background:var(--surface);border:1px solid var(--border);border-radius:calc(var(--radius) + 4px);padding:1.5em 1.5em 1.3em;box-shadow:0 30px 60px -20px rgba(0,0,0,.45);transform:translateY(14px) scale(.97);transition:transform calc(.35s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-mdl .scrim.open .dlg{transform:none}
.fx-mdl .dlg .hd{display:flex;align-items:flex-start;justify-content:space-between;gap:1em}
.fx-mdl .dlg h3{font-size:1.45em}
.fx-mdl .dlg .x{flex:none;width:2.1em;height:2.1em;border-radius:50%;border:0;background:transparent;color:var(--text);opacity:.6;cursor:pointer;font-size:1.1em;line-height:1;transition:background .2s,opacity .2s}
.fx-mdl .dlg .x:hover{background:color-mix(in srgb,var(--text) 8%,transparent);opacity:1}
.fx-mdl .dlg p{opacity:.7;margin:.5em 0 1.1em;font-size:.95em}
.fx-mdl .dlg label{display:block;font-size:.8em;font-weight:700;letter-spacing:.06em;text-transform:uppercase;opacity:.7;margin-bottom:.45em}
.fx-mdl .dlg input{width:100%;padding:.75em .9em;border-radius:var(--radius);border:1px solid var(--border);background:color-mix(in srgb,var(--surface) 97%,var(--text));color:var(--text);font:inherit}
.fx-mdl .dlg input:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 22%,transparent)}
.fx-mdl .dlg .ft{display:flex;justify-content:flex-end;gap:.6em;margin-top:1.3em;flex-wrap:wrap}
@media(prefers-reduced-motion:reduce){.fx-mdl .scrim,.fx-mdl .dlg{transition:none!important;animation:none!important}}
/* touch: :hover mirrored as .is-tap */
.fx-mdl .btn.is-tap{border-color:var(--primary);color:var(--primary)}
.fx-mdl .btn.pri.is-tap{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-mdl .dlg .x.is-tap{background:color-mix(in srgb,var(--text) 8%,transparent);opacity:1}

